package com.wanyuecity.energy.notification.controller;import com.wanyuecity.energy.core.ApiResponse;import com.wanyuecity.energy.notification.service.WebhookConfigService;import com.wanyuecity.energy.notification.service.dto.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/webhooks/config") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN')") public class WebhookConfigController {private final WebhookConfigService service;@GetMapping public ApiResponse<List<WebhookConfigView>> list(){return ApiResponse.ok(service.list());}@PostMapping public ApiResponse<WebhookConfigView> create(@Valid @RequestBody WebhookConfigRequest r){return ApiResponse.ok(service.save(null,r));}@PutMapping("/{id}")public ApiResponse<WebhookConfigView> update(@PathVariable Long id,@Valid @RequestBody WebhookConfigRequest r){return ApiResponse.ok(service.save(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void> delete(@PathVariable Long id){service.delete(id);return ApiResponse.ok();}}
